class Solution
{
public:
    bool validTree(int n, vector< vector< int >>& edges)
    {
        if ((int) edges.size() != n - 1)
        {
            return false;
        }
        vector< vector< int >>g(n);
        for (auto&e : edges)
        {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        vector< char>seen(n);
        queue< int>q;
        q.push(0);
        seen[0] = 1;
        int count = 0;
        while (!q.empty())
        {
            int u = q.front();
            q.pop();
            ++count;
            for (int v : g[u]) if(!seen[v])
            {
                seen[v] = 1;
                q.push(v);
            }
        }
        return count == n;
    }
};
